use fixture::invoice::invoice_line;
use fixture::money::format_cents;
use fixture::refund::refund_line;

#[test]
fn formats_cents() {
    let cases = [
        (0, "$0.00"),
        (5, "$0.05"),
        (99, "$0.99"),
        (100, "$1.00"),
        (1250, "$12.50"),
        (99_999, "$999.99"),
        (100_000, "$1,000.00"),
        (123_456, "$1,234.56"),
        (12_345_678, "$123,456.78"),
        (100_000_000, "$1,000,000.00"),
        (-1, "-$0.01"),
        (-5, "-$0.05"),
        (-100, "-$1.00"),
        (-12_345, "-$123.45"),
        (-123_456, "-$1,234.56"),
        (-100_000_000, "-$1,000,000.00"),
        (i64::MAX, "$92,233,720,368,547,758.07"),
        (i64::MIN, "-$92,233,720,368,547,758.08"),
    ];
    for (cents, expected) in cases {
        assert_eq!(format_cents(cents), expected, "format_cents({cents})");
    }
}

#[test]
fn lines_share_the_format() {
    for cents in [0, 7, 1205, 123_456, -5, -123_456, i64::MIN, i64::MAX] {
        assert_eq!(invoice_line(cents), format!("Total: {}", format_cents(cents)));
        assert_eq!(refund_line(cents), format!("Refund: {}", format_cents(cents)));
    }
    assert_eq!(invoice_line(123_450), "Total: $1,234.50");
    assert_eq!(refund_line(1205), "Refund: $12.05");
    assert_eq!(refund_line(-250_000), "Refund: -$2,500.00");
    assert_eq!(invoice_line(-123), "Total: -$1.23");
}
